import { readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

export type ToolCapability = 'instructions' | 'scoped_rules' | 'skills' | 'commands' | 'hooks' | 'mcp' | 'agents' | 'subagents';
export interface ToolCapabilities { instructions:boolean; scoped_rules:boolean; skills:boolean; commands:boolean; hooks:boolean; mcp:boolean; agents:boolean; subagents:boolean; }
export interface GeneratedFile { path:string; content:string; }
export interface MidnightAdapter { id:string; detect(projectRoot:string):boolean; capabilities():ToolCapabilities; render(projectRoot:string):GeneratedFile[]; validate?(projectRoot:string):string[]; }
export type AdapterFileKind = 'instruction' | 'skill' | 'cursor-rule';
export interface AdapterFileContract { path:string; kind:AdapterFileKind; }
export interface TierAContracts { schema:string; tools: Record<string, { files: AdapterFileContract[] }>; }

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');

function readJsonish(path: string): any { return JSON.parse(readFileSync(path, 'utf8')); }

export function loadAdapterRegistry(): any {
  return readJsonish(join(ROOT, 'packages/adapters/registry.yaml'));
}

export function loadTierAContracts(): TierAContracts {
  return readJsonish(join(ROOT, 'packages/adapters/contracts/tier-a.yaml'));
}

export function globToRegExp(glob: string): RegExp {
  let out='';
  for (const c of glob) {
    if (c === '*') out += '[^/]+';
    else if ('.+^${}()|[]\\'.includes(c)) out += '\\' + c;
    else out += c;
  }
  return new RegExp(`^${out}$`);
}

export function matchesNativeOutput(path: string, globs: string[]): boolean {
  return globs.some(glob => globToRegExp(glob).test(path));
}

function parseFrontmatter(content: string): { attrs: Record<string, string>, body: string } | null {
  const normalized=content.replace(/^\uFEFF/, '');
  if (!normalized.startsWith('---\n') && !normalized.startsWith('---\r\n')) return null;
  const nl=normalized.startsWith('---\r\n') ? '\r\n' : '\n';
  const end=normalized.indexOf(`${nl}---`, 4);
  if (end < 0) return null;
  const raw=normalized.slice(3 + nl.length, end);
  const attrs: Record<string, string> = {};
  for (const line of raw.split(/\r?\n/)) {
    const i=line.indexOf(':');
    if (i > 0) attrs[line.slice(0,i).trim()] = line.slice(i+1).trim();
  }
  const bodyStart=end + nl.length + 3;
  return { attrs, body: normalized.slice(bodyStart).replace(/^\r?\n/, '') };
}

function hasGeneratedHeader(content: string, adapter: string): string[] {
  const failures: string[]=[];
  if (!content.includes('<!-- Generated by Midnight.')) failures.push(`${adapter} missing generated header`);
  if (!content.includes(`adapter: ${adapter}`)) failures.push(`${adapter} missing adapter identity`);
  if (!content.includes('Midnight Core Constitution')) failures.push(`${adapter} missing constitution projection`);
  return failures;
}

export function validateAdapterFile(adapter: string, path: string, content: string): string[] {
  const contracts=loadTierAContracts();
  const spec=contracts.tools[adapter]?.files.find(file => file.path === path);
  if (!spec) return [`${adapter} unexpected path ${path}`];
  if (spec.kind === 'instruction') return hasGeneratedHeader(content, adapter).map(msg => `${path}: ${msg}`);
  if (spec.kind === 'skill') {
    const fm=parseFrontmatter(content);
    const failures: string[]=[];
    if (!fm) failures.push(`${path}: missing YAML frontmatter`);
    else {
      if (fm.attrs.name !== 'midnight') failures.push(`${path}: skill name must be midnight`);
      if (!fm.attrs.description) failures.push(`${path}: skill description must be present`);
      if (!fm.body.includes('Deterministic commands')) failures.push(`${path}: skill missing deterministic commands`);
      if (!fm.body.includes('midnight lint')) failures.push(`${path}: skill missing midnight lint`);
    }
    return failures;
  }
  if (spec.kind === 'cursor-rule') {
    const fm=parseFrontmatter(content);
    const failures: string[]=[];
    if (!fm) failures.push(`${path}: missing YAML frontmatter`);
    else {
      if (fm.attrs.alwaysApply !== 'true') failures.push(`${path}: alwaysApply must be true`);
      if (!fm.attrs.description) failures.push(`${path}: description must be present`);
      failures.push(...hasGeneratedHeader(fm.body, adapter).map(msg => `${path}: ${msg}`));
    }
    return failures;
  }
  return [`${path}: unknown kind ${spec.kind}`];
}

export function validatePlannedProjections(planned: Array<[string, string, string?]>): string[] {
  const contracts=loadTierAContracts();
  const byTool=new Map<string, Array<[string, string]>>();
  for (const [path, content, tool] of planned) {
    if (!tool || !contracts.tools[tool]) continue;
    const list=byTool.get(tool) || [];
    list.push([path, content]);
    byTool.set(tool, list);
  }
  const failures: string[]=[];
  for (const [tool, files] of byTool) {
    const expected=new Set((contracts.tools[tool].files || []).map(file => file.path));
    const got=new Set(files.map(([path]) => path));
    for (const path of expected) if (!got.has(path)) failures.push(`${tool} missing ${path}`);
    for (const [path, content] of files) failures.push(...validateAdapterFile(tool, path, content));
  }
  return failures;
}

export function tierAToolIds(): string[] {
  return Object.keys(loadTierAContracts().tools || {});
}

export function registryTierAToolIds(): string[] {
  const tools=loadAdapterRegistry().tools || {};
  return Object.keys(tools).filter((id: string) => tools[id]?.tier === 'A');
}
